/* @autogenerated */
package net.civeira.phylax.testing.cache;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;
import java.util.function.Predicate;

import io.quarkus.cache.Cache;
import io.smallrye.mutiny.Uni;

/**
 * A quarkus cache on memory for the unit tests: get only runs the loader when the key is absent
 * (and a null loaded value is not stored).
 */
public class InMemoryCache implements Cache {
  private final String name;
  private final Map<Object, Object> values = new ConcurrentHashMap<>();

  public InMemoryCache(String name) {
    this.name = name;
  }

  /** The stored values. */
  public Map<Object, Object> values() {
    return values;
  }

  @Override
  public String getName() {
    return name;
  }

  @Override
  public Object getDefaultKey() {
    return "default";
  }

  @Override
  @SuppressWarnings("unchecked")
  public <K, V> Uni<V> get(K key, Function<K, V> valueLoader) {
    return Uni.createFrom().item((V) values.computeIfAbsent(key, k -> valueLoader.apply((K) k)));
  }

  @Override
  @SuppressWarnings("unchecked")
  public <K, V> Uni<V> getAsync(K key, Function<K, Uni<V>> valueLoader) {
    if (values.containsKey(key)) {
      return Uni.createFrom().item((V) values.get(key));
    }
    return valueLoader.apply(key).invoke(value -> {
      if (null != value) {
        values.put(key, value);
      }
    });
  }

  @Override
  public Uni<Void> invalidate(Object key) {
    values.remove(key);
    return Uni.createFrom().voidItem();
  }

  @Override
  public Uni<Void> invalidateAll() {
    values.clear();
    return Uni.createFrom().voidItem();
  }

  @Override
  public Uni<Void> invalidateIf(Predicate<Object> predicate) {
    values.keySet().removeIf(predicate);
    return Uni.createFrom().voidItem();
  }

  @Override
  public <T extends Cache> T as(Class<T> type) {
    throw new IllegalStateException("Not a " + type);
  }
}
